from robot.libraries.BuiltIn import BuiltIn
from taf.config.testline import Simulator, Airphone, CommonUnit, CoreUnit

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_env_state, log_operation
from taf.rfrl.procedures.resources.python.testline.exceptions import CouldNotGetConfigType, IncorrectBTSType, \
    CouldNotGetSlaveTestPC, RmodCredentialsNotFound, TestPCNotFound, MissingInitParameter, SmodSerialNumberUnavailable
from taf.rfrl.procedures.resources.python.utilities import remove_duplicates_and_preserve_order


class TestLine(object):
    """
    Responsible for collecting information about configuration objects from current Testline configuration.

    """
    @property
    def current_config(self):
        return BuiltIn().get_variable_value('${tl}')

    @log_input_and_output
    def get_mrbts_id(self):
        """
        Gets mrbts id from init file.

        :return: MRBTS id nubmer
        :rtype: int
        """
        return self.current_config.gnbs[0].instance_id

    @log_input_and_output
    def get_bts_test_pc_credentials(self, bts_type, slave=False, bts_id=0):
        """
        Returns Test PC ssh connection details for provided BTS Type GNB or ENB

        :param bts_type: GNB or ENB
        :type bts_type: str
        :param slave: subordinate BTS; defaults to False.
        :type slave: boolean
        :param bts_id: init index of bts to get credentials; defaults to 0.
        :type bts_id: int or str
        :return: login details for ssh connection, eg. {'host': '1.1.1.1', 'user': 'ute', 'password': 'ute'}
        :rtype: dict
        """
        test_pc = self._get_proper_test_pc_from_list(bts_type=bts_type, slave=slave, bts_id=int(bts_id))

        credentials = {
            'host': test_pc.default_ssh_connection_details.addr,
            'user': test_pc.default_ssh_connection_details.username,
            'password': test_pc.default_ssh_connection_details.password
        }

        return credentials

    @log_input_and_output
    def is_full_rack(self, bts_type="GNB", bts_id=0):
        """
        Determines whether testline is full rack configuration by checking number of system modules in init.

        :param bts_type: BTS type 'GNB' or 'ENB' of which the full rack validation should be performed
        :type bts_type: str
        :param bts_id: init index of bts for which the full rack validation should be performed; default is 0.
        :type bts_id: int or str
        :return: True if full rack, False otherwise
        :rtype:  bool
        """
        smods = self._get_smods_configs(bts_id=int(bts_id), bts_type=bts_type)

        return len(smods) > 1

    @log_input_and_output
    def is_simulated(self):
        """
        Determines whether testline uses simulator or real HW.

        :return: True if simulated, False otherwise
        :rtype: bool
        """
        return any((isinstance(ue, Simulator) or isinstance(ue, Airphone))
                   for ue in self.current_config.ues) if self.current_config.ues else False

    @log_input_and_output
    def get_type_of_setup(self):
        """
        Gets type of setup (GNB or ENB) from tl topology init file.
        :return: Type of testline
        :rtype: String
        :raises CouldNotGetConfigType: when there were no gnbs nor enbs in configuration file
        """
        if self.current_config.gnbs:
            return 'GNB'
        elif self.current_config.enbs:
            return 'ENB'

        raise CouldNotGetConfigType('Could not find gnbs nor enbs in configuration file. '
                                    'Please review your init file.')

    @log_input_and_output
    def get_bts_setup_mode(self):
        """
        Gets bts setup mode (SA or NSA) from tl topology init file.
        :return: Type of setup mode
        :rtype: String
        :raises CouldNotGetConfigType: when there were no gnbs nor enbs in configuration file
        """
        if self.current_config.gnbs and self.current_config.enbs:
            return 'NSA'
        elif self.current_config.gnbs or self.current_config.enbs:
            return 'SA'

        raise CouldNotGetConfigType('Could not find gnbs nor enbs in configuration file. '
                                    'Please review your init file.')

    @log_input_and_output
    def get_smods_configs(self, bts_type='GNB', bts_id=None, custom_init=None):
        """
        Gets GNB system modules config from init file

        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
        :type bts_type: str
        :param bts_id: init index of bts for which the SMODs config should be returned.
                       Default value is None, which mean all gnbs/enbs objects will be checked.
        :type bts_id: int or str or None
        :param custom_init: Custom init file to use instead of current tl configuration; default value None.
        :type custom_init: taf.config.testline.TestLine or None
        :return: list of CommonUnit instances
        :rtype:  list(CommonUnit)
        """
        return self._get_smods_configs(bts_id=bts_id, bts_type=bts_type, custom_init=custom_init)

    @log_input_and_output
    def get_smods_ip_addresses(self, bts_type='GNB'):
        """
        Gets IP addresses of all system modules from configuration init file

        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'
        :type bts_type: str
        :return list of IP addresses of all system modules
        :rtype: list of str
        """
        return [smod.lmp_connection.addr for smod in self.get_smods_configs(bts_type)]

    @log_input_and_output
    def get_smod_ip_from_local_test_pc(self):
        """
        Returns IP address of SMOD connected to local Test PC.
        """
        return self._get_smod_ip_from_local_test_pc()

    @log_input_and_output
    def get_smod_serial_number(self, smod_id=0, bts_type='GNB'):
        """
        Gets serial number of gNB SMOD with given ID.
        :param smod_id: ID of SMOD which should be checked in TL config; defaults to 0 (first SMOD in config)
        :type smod_id: int
        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'
        :type bts_type: str
        :return: serial number of SMOD
        :rtype: str
        """
        return self._get_smods_configs(bts_type=bts_type)[int(smod_id)].serial_number

    @log_input_and_output
    def get_bbmods_configs(self, bts_type='GNB', bts_id=None, custom_init=None):
        """
        Gets GNB baseband modules config from init file

        :param bts_type: BTS type 'GNB' or 'ENB' of which the bbmods config should be returned; default value 'GNB'
        :type bts_type: str
        :param bts_id: init index of bts for which the CapacityUnit config should be returned.
                       Default value is None, which mean all gnbs/enbs objects will be checked.
        :type bts_id: int or str or None
        :param custom_init: Custom init file to use instead of current tl configuration; default value None.
        :type custom_init: taf.config.testline.TestLine or None
        :return: list of CapacityUnit instances
        :rtype:  list(CapacityUnit)
        """

        return self._get_capacity_units_configs(bts_id=bts_id, bts_type=bts_type, custom_init=custom_init)

    @log_input_and_output
    def get_radio_serial_number(self, ru_id=0):
        """
        Returns serial number of radio from current TL configuration, i.e. 'YK203400326'

        :param ru_id: ID of RU which should be checked in TL config; default value is 0 (first RU in config)
        :type ru_id: int
        :return: serial number of given radio
        :rtype: str
        """
        try:
            return self._get_radios_configs()[int(ru_id)].serial_number

        except IndexError:
            raise IndexError('There is no RU with ID: {}'.format(ru_id))

    @log_input_and_output
    def get_alds_serials_from_init(self, bts_type="GNB"):
        """
        Gets alds serial numbers from init file, defined only for provided BTS type.
        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
                         Parameter is not case-sensitive so will accept values as long as the spelling is correct.
        :type bts_type: str
        :return: list of ALDs serials. In case of no ALDs in configuration, returns empty list.
        :rtype: list
        """
        ald_list = self.get_alds_config(bts_type=bts_type)

        return [ald.serial_number for ald in ald_list]

    @log_input_and_output
    def get_alds_config(self, bts_type="GNB"):
        """
        Gets list of configurations for all ALDs defined in radio unit objects, for particular bts type.
        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
                         Parameter is not case-sensitive so will accept values as long as the spelling is correct.
        :type bts_type: str
        :return: list of configurations for all ALDs
        :rtype: list
        """
        rus_list = self._get_radios_configs(bts_type=bts_type)

        return self._get_alds_list_from_rus_objects(rus_list)

    @log_input_and_output
    def get_rus_id_and_serial(self, bts_type='GNB'):
        """
        Gets ids and serials of all radio modules included in init file.

        :return: Dictionary of ru id (key) and ru serial (value)
        :rtype: dict
        """
        id_serial = {}
        radios = self._get_radios_configs(bts_type=bts_type)
        for ru_id, radio in enumerate(radios):
            id_serial[ru_id] = radio.serial_number

        log_env_state("RUs id and serial numbers read from init file: {}".format(id_serial))

        return id_serial

    @log_input_and_output
    def get_radios_configs(self, bts_type='GNB', bts_id=None, custom_init=None):
        """
        Returns configuration objects of all radios for given gNB and DU from current Tl configuration

        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
                         Parameter is not case-sensitive so will accept values as long as the spelling is correct.
        :type bts_type: str
        :param bts_id: init index of bts for which the SMODs config should be returned.
                       Default value is None, which mean all gnbs/enbs objects will be checked.
        :type bts_id: int or str or None
        :param custom_init: Custom init file to use instead of current tl configuration; default value None.
        :type custom_init: taf.config.testline.TestLine or None

        :return: Radios configurations
        :rtype: list(RU)
        """
        return self._get_radios_configs(bts_id=bts_id, bts_type=bts_type, custom_init=custom_init)

    def get_count_of_radios(self, bts_type='GNB'):
        """
        Get count of radios from configuration init file for particular bts type (GNB or ENB)

        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
                         Parameter is not case-sensitive so will accept values as long as the spelling is correct.
        :type bts_type: str
        :return: Radios count
        :rtype: int
        """
        radios_count = len(self._get_radios_configs(bts_type=bts_type))
        log_env_state("RUs count for {} read from init file: {}".format(bts_type, radios_count))

        return radios_count

    @log_input_and_output
    def get_rmod_authentication_credential(self, rmod_id, sw_stream):
        """
        Gets Rmod ssh login credentials (username and password) for provided sw stream from init file
        :param rmod_id: Id number of desired Rmod credentials.
        :type rmod_id: int
        :param sw_stream: Type of desired credentials (username or password)
        :type sw_stream: str
        :return: Provided type of credentials for given Rmod ID
        :rtype: str
        """
        log_operation("Collecting Rmod authentication credential...")
        try:
            credential = self._get_radios_configs()[int(rmod_id)].default_ssh_connection_details

        except IndexError:
            raise IndexError('There is no Rmod with ID: {}'.format(rmod_id))

        log_env_state("Read rmod config credential values: {0}".format(credential))

        return self._get_proper_rmod_credentials(credential=credential, sw_stream=sw_stream)

    def get_rmod_credentials_by_sn(self, rmod_sn, sw_stream=None):
        """
        Returns RMOD ssh credentials based on given serial number and sw stream.

        :param rmod_sn: Serial number of RMOD.
        :type rmod_sn: str
        :param sw_stream: Proper SW stream on based which address, username and password will be selected from init
                          (RU.default_ssh_connection_details) to establish rmod ssh connection e.g SBTS23R3. Default None.
        :type sw_stream: str
        :return: Credentials based on given sw stream. e.g. ('rfsw', 'password')
        :rtype: tuple[str, str]
        :raise: RmodCredentialsNotFound If there is no RMOD serial number in the init file.
        """
        log_operation("Collecting Rmod authentication credential...")
        tl_rmods = self._get_radios_configs()

        for rmod in tl_rmods:
            if rmod.serial_number == rmod_sn:
                log_env_state(f"Read rmod config credential values: {rmod.default_ssh_connection_details}")
                return self._get_proper_rmod_credentials(credential=rmod.default_ssh_connection_details, sw_stream=sw_stream)

        raise RmodCredentialsNotFound(f"Could not find RMOD with serial number: {rmod_sn} in init file")

    def get_rmod_config_by_serial_number(self, ru_serial_number):
        """
        Returns configuration object of specific radio for given gNB and DU from current Tl configuration

        :param ru_serial_number: Serial number of RMOD.
        :type ru_serial_number: str
        :return: Radio configuration
        :rtype: list(RU)
        """
        tl_rmods = self._get_radios_configs()

        for rmod in tl_rmods:
            if rmod.serial_number == ru_serial_number:
                return rmod

    @log_input_and_output
    def get_radios_per_smod(self, smod):
        """
        Returns all radio modules connected to given system module
        :param smod: System Module's init representation with `capacity_units` attribute. (it is required to have all
                     rus objects plugged in appropriate CapacityUnits via `rmods` attribute).
        :type smod: CommonUnit class
        :return: list of Rmod objects that are plugged into baseband modules connected with system module
        provided by user.
        :rtype: list(Rmod)
        """
        rmods = []
        bbmods = self._get_capacity_units_from_smod(smod)

        for bbmod in bbmods:
            bbmods_rmods = self._get_rmods_list_from_bbmod(bbmod)
            for rmod in bbmods_rmods:
                log_env_state("Checking if Rmod: {0} is not already in Rmods list...".format(rmod))
                if rmod not in rmods:
                    log_operation("New RMOD detected! Expanding RMODs list.")
                    rmods.append(rmod)

        return rmods

    @log_input_and_output
    def get_init_index_of_rmod_with_serial_number(self, serial_number, bts_type='GNB'):
        """
        Returns init index of rmod with serial number provided.
        :param serial_number: serial number of desired rmod
        :type serial_number: str
        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods config should be returned; default value 'GNB'.
                         Parameter is not case-sensitive so will accept values as long as the spelling is correct.
        :type bts_type: str
        :return: init index of rmod with serial
        :rtype: int
        """
        rmods_configs = self._get_radios_configs(bts_type=bts_type)

        for rmod in rmods_configs:
            if rmod.serial_number == serial_number:
                return rmods_configs.index(rmod)

    def get_serial_numbers_of_all_rmods_from_init(self, bts_type='GNB', custom_init=None):
        """
        Returns list with rmods serial numbers from init file.

        :param bts_type: BTS type 'GNB' or 'ENB' of which the rmods serial numbers should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :param custom_init: Custom init file to use instead of current tl configuration; default value None.
        :type custom_init: taf.config.testline.TestLine or None
        :return: Lists of RMODs serial numbers
        :rtype: [str]
        """

        return [rmod.serial_number for rmod in self._get_radios_configs(bts_type=bts_type, custom_init=custom_init)]

    def get_serial_numbers_of_all_smods_from_init(self, bts_type='GNB'):
        """
        Returns list with smods serial numbers from init file.
        :param bts_type: BTS type 'GNB' or 'ENB' of which the smods serial numbers should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :return: Lists of SMODs serial numbers
        :rtype: [str]
        """
        return [smod_config.serial_number for smod_config in self._get_smods_configs(bts_type=bts_type)]

    @log_input_and_output
    def get_product_codes_of_all_cabinets_from_init(self, bts_type='GNB'):
        """
        Returns product codes of all CABINETs from init file.
        If any CABINET does not have product code defined in init file, then it will not be returned.
        :param bts_type: BTS type 'GNB' or 'ENB' of which product codes of all CABINETs should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :return: List of CABINETs product codes, e.g. ['473098A', '473098B']
        :rtype: list[str]
        """
        cabinets_configs = self._get_cabinets_configs(bts_type=bts_type)
        return [cabinet_config.product_code for cabinet_config in cabinets_configs if getattr(cabinet_config, 'product_code', None)]

    @log_input_and_output
    def get_serial_numbers_and_product_codes_of_all_smods_from_init(self, bts_type='GNB'):
        """
        Returns list of dictionaries with serial numbers and product codes of all SMODs from init file.
        If any SMOD does not have serial number or product code defined in init file, then it will not be returned.
        :param bts_type: BTS type 'GNB' or 'ENB' of which SMODs serial numbers and product codes should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :return: Dictionary with serial numbers and product codes of all SMODs,
                 e.g. {'L1232304192': '474767A.103',
                       'L1232304183': '474767X.101'}
        :rtype: dict[str, str]
        """
        smods_configs = self._get_smods_configs(bts_type=bts_type)
        return {smod_config.serial_number: smod_config.product_code
                for smod_config in smods_configs
                if getattr(smod_config, 'serial_number', None) and getattr(smod_config, 'product_code', None)}

    @log_input_and_output
    def get_serial_numbers_and_product_codes_of_all_bbmods_from_init(self, bts_type='GNB'):
        """
        Returns list of dictionaries with serial numbers and product codes of all BBMODs from init file.
        If any BBMOD does not have serial number or product code defined in init file, then it will not be returned.
        :param bts_type: BTS type 'GNB' or 'ENB' of which BBMODs serial numbers and product codes should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :return: Dictionary with serial numbers and product codes of all BBMODs,
                 e.g. {'L1232004108': '475792A.101',
                       'L1232004111': '475792A.103'}
        :rtype: dict[str, str]
        """
        bbmods_configs = self._get_capacity_units_configs(bts_type=bts_type)
        return {bbmod_config.serial_number: bbmod_config.product_code
                for bbmod_config in bbmods_configs
                if getattr(bbmod_config, 'serial_number', None) and getattr(bbmod_config, 'product_code', None)}

    @log_input_and_output
    def get_serial_numbers_and_product_codes_of_all_rmods_from_init(self, bts_type='GNB'):
        """
        Returns list of dictionaries with serial numbers and product codes of all RMODs from init file.
        If any RMOD does not have serial number or product code defined in init file, then it will not be returned.
        :param bts_type: BTS type 'GNB' or 'ENB' of which RMODs serial numbers and product codes should be returned;
                         default value 'GNB'.
        :type bts_type: str
        :return: Dictionary with serial numbers and product codes of all RMODs,
                 e.g. {'AH221500786': '475432A.101',
                       'AH221500678': '475432A.103'}
        :rtype: dict[str, str]
        """
        rmods_configs = self._get_radios_configs(bts_type=bts_type)
        return {rmod_config.serial_number: rmod_config.product_code
                for rmod_config in rmods_configs
                if getattr(rmod_config, 'serial_number', None) and getattr(rmod_config, 'product_code', None)}

    def get_ip_of_secondary_vm_for_fullrack(self):
        """
        Returns IP address of secondary VM for full rack configuration.
        """
        return self._get_proper_test_pc_from_list(bts_type="GNB", slave=True).default_ssh_connection_details.addr

    def get_http_credentials(self, bts_type="GNB", bts_id=0):
        """
        Returns http credentials for bts of type bts_type
        :param bts_type: BTS type 'GNB' or 'ENB' of which http credentials should be returned; default value 'GNB'.
        :type bts_type: str
        :param bts_id: ID of BTS for which http credentials should be returned; default value 0.
        :type bts_id: int
        :returns: http credentials for bts of type bts_type
        :rtype: dict
        """
        return self._get_http_credentials_for_gnb(int(bts_id)) if bts_type == "GNB" \
            else self._get_http_credentials_for_enb(int(bts_id))

    def get_ssh_credentials(self, bts_type="GNB", bts_id=0, common_unit_id=0):
        """
        Returns ssh credentials for bts of type bts_type
        :param bts_type: BTS type 'GNB' or 'ENB' of which ssh credentials should be returned; default value 'GNB'.
        :type bts_type: str
        :param bts_id: ID of BTS for which ssh credentials should be returned; default value 0.
        :type bts_id: int
        :param common_unit_id: ID of Common Unit for which ssh credentials should be returned; default value 0.
        :type common_unit_id: int
        :returns: ssh credentials for bts of type bts_type
        :rtype: dict
        """
        return self._get_ssh_credentials_for_gnb(bts_id=int(bts_id), cu_id=int(common_unit_id)) if bts_type == "GNB" \
            else self._get_ssh_credentials_for_enb(bts_id=int(bts_id), cu_id=int(common_unit_id))

    @log_input_and_output
    def get_smod_serial_number_by_vm_ip_address(self, vm_ip):
        """
        Returns serial number of SMOD connected to Test_pc based on given test_pc ip address.
        :param vm_ip: IP address of VM
        :type vm_ip: str
        :return: serial number of SMOD connected to VM with given IP address
        :rtype: str
        """
        return self._get_smod_serial_number_from_test_pc(vm_ip)

    @log_input_and_output
    def get_vlan_id(self, bts_id=0):
        """
        Returns VLAN ID for given bts_id.
        :param bts_id: ID of BTS for which VLAN ID should be returned; default value 0.
        :type bts_id: int
        :return: VLAN ID for given bts_id
        :rtype: int
        :raises MissingInitParameter: when VLAN ID is not found in init file
        """
        for interface in ["s1u", "x2u", "x2c"]:
            try:
                return getattr(self.current_config.gnbs[int(bts_id)].cu, interface).vlan_id
            except AttributeError:
                pass
        raise MissingInitParameter("VLAN ID not found in init file. Please check your init file.")

    def _get_ssh_credentials_for_gnb(self, bts_id, cu_id):
        airscale = self.current_config.gnbs[bts_id].dus[0].airscale
        if airscale.common_units:
            lmp_connection = airscale.common_units[cu_id].lmp_connection
        else:
            lmp_connection = airscale.core_units[cu_id].lmp_connection

        credentials = {
            "username": lmp_connection.username,
            "password": lmp_connection.password,
            "host": lmp_connection.addr,
        }
        return credentials

    def _get_ssh_credentials_for_enb(self, bts_id, cu_id):
        if airscale := self.current_config.enbs[bts_id].airscale:
            lmp_connection = airscale.common_units[cu_id].lmp_connection
        else:
            lmp_connection = self.current_config.enbs[bts_id].system_module.common_units[cu_id].lmp_connection

        credentials = {
            "username": lmp_connection.username,
            "password": lmp_connection.password,
            "host": lmp_connection.addr,
        }
        return credentials

    def _get_http_credentials_for_gnb(self, bts_id):
        credentials = {
            "ip": self.current_config.gnbs[bts_id].cu.oam_http_connection_details.addr,
            "username": self.current_config.gnbs[bts_id].cu.oam_http_connection_details.username,
            "password": self.current_config.gnbs[bts_id].cu.oam_http_connection_details.password,
            "port": self.current_config.gnbs[bts_id].cu.oam_http_connection_details.port
        }
        return credentials

