    @log_input_and_output
    def _get_proper_test_pc_from_list(self, bts_type, slave=False, bts_id=0):

        test_pcs_for_airscale_units_serial_numbers = self._get_all_test_pcs_for_smod_serial_numbers()
        airscale_unit_serial_number = self._get_airscale_smod_serial_number_for_smod(bts_type=bts_type,
                                                                                     slave=slave,
                                                                                     bts_id=bts_id)

        if test_pcs_for_airscale_units_serial_numbers.get(airscale_unit_serial_number):
            return test_pcs_for_airscale_units_serial_numbers[airscale_unit_serial_number]

        raise TestPCNotFound(f'Test PC could not be found for airscale common unit serial number: '
                             f'{airscale_unit_serial_number}')

    @log_input_and_output
    def _get_airscale_smod_serial_number_for_smod(self, bts_type, slave, bts_id):
        smod_index = 1 if slave else 0

        if bts_type.upper() == "GNB":
            if self.current_config.gnbs:
                airscale = self.current_config.gnbs[bts_id].dus[0].airscale
                gnb_smods = airscale.common_units if airscale.common_units else airscale.core_units
                if slave and len(gnb_smods) == 1:
                    raise CouldNotGetSlaveTestPC('Could not find TestPc for slave gnb in configuration file. '
                                                 'Please review your init file.')
                self._verify_serial_number_parameter_under_smod_unit(gnb_smods[smod_index])
                return gnb_smods[smod_index].serial_number

            raise CouldNotGetConfigType('Could not find gnbs in configuration file. Please review your init file.')

        elif bts_type.upper() == "ENB":
            if self.current_config.enbs:
                if hasattr(self.current_config.enbs[bts_id], 'system_module') and \
                        self.current_config.enbs[bts_id].system_module is not None:
                    enb_bts_module = self.current_config.enbs[bts_id].system_module
                elif hasattr(self.current_config.enbs[bts_id], 'airscale') and \
                        self.current_config.enbs[bts_id].airscale is not None:
                    enb_bts_module = self.current_config.enbs[bts_id].airscale
                else:
                    raise MissingInitParameter("'Airscale' object cannot be found under enb module")

                enb_smods = enb_bts_module.common_units if enb_bts_module.common_units else enb_bts_module.core_units
                if slave and len(enb_smods) == 1:
                    raise CouldNotGetSlaveTestPC('Could not find TestPc for slave enb in configuration file. '
                                                 'Please review your init file.')
                self._verify_serial_number_parameter_under_smod_unit(enb_smods[smod_index])
                return enb_smods[smod_index].serial_number
            raise CouldNotGetConfigType('Could not find enbs in configuration file. Please review your init file.')

        raise IncorrectBTSType("Provided BTS type is neither 'GNB' nor 'ENB'.")

    @log_input_and_output
    def _get_all_test_pcs_for_smod_serial_numbers(self):
        self._verify_list_of_test_pcs()

        dict_test_pcs_for_smods_serial_numbers = {}
        for test_pc in self.current_config.test_pcs:
            for connection in test_pc.connections:
                connected_device = getattr(connection, 'device', connection)

                airscale = None
                if hasattr(connected_device, 'system_module') and connected_device.system_module is not None:
                    airscale = connected_device.system_module
                elif hasattr(connected_device, 'airscale') and connected_device.airscale is not None:
                    airscale = connected_device.airscale

                if airscale:
                    if common_units := airscale.common_units:
                        smod_unit = common_units[0]
                    elif core_units := airscale.core_units:
                        smod_unit = core_units[0]
                else:
                    smod_unit = connected_device

                if not isinstance(smod_unit, (CommonUnit, CoreUnit)):
                    continue
                dict_test_pcs_for_smods_serial_numbers[smod_unit.serial_number] = test_pc

        return dict_test_pcs_for_smods_serial_numbers

    @staticmethod
    def _verify_serial_number_parameter_under_smod_unit(smod_object):
        if not hasattr(smod_object, 'serial_number'):
            raise MissingInitParameter(f"Parameter 'serial_number' is not defined for airscale SMOD unit: "
                                       f"{smod_object}. Please review your init file.")

    @log_input_and_output
    def _verify_list_of_test_pcs(self):
        for test_pc in self.current_config.test_pcs:
            if not hasattr(test_pc, 'connections') or not test_pc.connections:
                raise MissingInitParameter(f"Incorrect 'connections' definition in test PC: {test_pc}. "
                                           f"Please review your init file.")

    @staticmethod
    def _get_alds_list_from_rus_objects(rus_list):
        alds_list = []
        for ru in rus_list:
            try:
                for ald in ru.alds:
                    alds_list.append(ald)
            except AttributeError:
                continue
        return alds_list

    def _get_radios_configs(self, bts_id=None, bts_type='GNB', custom_init=None):
        testline_config = self.current_config if custom_init is None else custom_init
        radio_configs = []
        if bts_type == "GNB":
            gnbs = testline_config.gnbs if bts_id is None else [testline_config.gnbs[int(bts_id)]]
            for gnb in gnbs:
                for du in gnb.dus:
                    if du.rus:
                        radio_configs.extend(du.rus)
                    else:
                        if common_units := du.airscale.common_units:
                            for common_unit in common_units:
                                if common_unit.rus:
                                    radio_configs.extend(common_unit.rus)
                                for capacity_unit in common_unit.capacity_units:
                                    if capacity_unit.rus:
                                        radio_configs.extend(capacity_unit.rus)
                        elif core_units := du.airscale.core_units:
                            for core_unit in core_units:
                                radio_configs.extend(core_unit.rus)

        elif bts_type == "ENB":
            enbs = testline_config.enbs if bts_id is None else [testline_config.enbs[int(bts_id)]]
            for enb in enbs:
                airscale = enb.airscale if enb.airscale else enb.system_module
                if enb.rms:
                    radio_configs.extend(enb.rms)
                else:
                    if common_units := airscale.common_units:
                        for common_unit in common_units:
                            if common_unit.rus:
                                radio_configs.extend(common_unit.rus)
                            for capacity_unit in common_unit.capacity_units:
                                if capacity_unit.rus:
                                    radio_configs.extend(capacity_unit.rus)
                    elif core_units := airscale.core_units:
                        for core_unit in core_units:
                            radio_configs.extend(core_unit.rus)

        else:
            raise IncorrectBTSType("Provided BTS type is neither 'GNB' nor 'ENB'.")

        radio_configs = remove_duplicates_and_preserve_order(radio_configs)
        log_env_state("RUs read from init file: {}".format(
            [{"serial_number": configs.serial_number, "ru_type": configs.radio_type}
             for configs in radio_configs]))

        return radio_configs

