    @staticmethod
    def _get_capacity_units_from_smod(smod):
        try:
            bbmods = smod.capacity_units
            log_env_state("Read Capacity Units of provided SMOD: {0}".format(bbmods))

            if len(bbmods):
                log_operation("Some capacity units has been detected!")
                return bbmods
            else:
                raise LookupError("It seems like Your capacity units list is empty,"
                                  " please repair Your init configuration file.")
        except AttributeError:
            raise AttributeError("It looks like Your System Module object does not have `capacity_units` attribute, "
                                 "please repair Your init configuration file.")

    @staticmethod
    def _get_rmods_list_from_bbmod(bbmod):
        try:
            bbmod_rmods = bbmod.rus

            if len(bbmod_rmods):
                log_env_state("Rmods detected in bbmod: {0}".format(bbmod_rmods))
                return bbmod_rmods
            else:
                raise LookupError("It seems like baseband module: {0} has empty `rmods` list in init "
                                  "configuration file - It should be fixed.".format(bbmod))
        except AttributeError:
            raise AttributeError("It seems like some of Your baseband module does not have defined `rmods` list "
                                 "in init configuration file - please fix this.")

    def _get_proper_rmod_credentials(self, credential, sw_stream):
        """
        Returns proper rmod ssh credentials based on given sw stream.
        :param credential: RMOD init representation with `default_ssh_connection_details` attribute.
        :type credential: init RU class
        :param sw_stream: Proper SW stream on based which address, username and password will be selected from init
                          (RU.default_ssh_connection_details) to establish rmod ssh connection e.g SBTS23R3.
        :type sw_stream: str
        :return: Credentials based on given sw stream e.g. ('rfsw', '3Is6ezFJ7dFlB')
        :rtype: tuple[str, str]
        :raise: RmodCredentialsNotFound if there's no credentials for provided sw_stream
        """
        try:
            if isinstance(credential.username, dict) and isinstance(credential.password, dict):
                log_operation("Returning credentials suited to {0} branch".format(sw_stream))
                return credential.username[sw_stream], credential.password[sw_stream]

            elif not isinstance(credential.username, dict) and isinstance(credential.password, dict):
                log_operation("Single username value detected! "
                              "Returning credentials suited to {0} branch".format(sw_stream))
                return credential.username, credential.password[sw_stream]

            elif isinstance(credential.username, dict) and not isinstance(credential.password, dict):
                log_operation("Single password value detected! "
                              "Returning credentials suited to {0} branch".format(sw_stream))
                return credential.username[sw_stream], credential.password

        except KeyError:
            raise RmodCredentialsNotFound("It seems like there is no credentials for asked {0} stream in rmod init".
                                          format(sw_stream))

        log_operation("Single credential values detected, returning...")
        return credential.username, credential.password

    def _get_smod_serial_number_from_test_pc(self, test_pc_ip):
        """
        Returns serial number of SMOD connected to Test PC.
        :param test_pc_ip: IP address of Test PC
        :type test_pc_ip: str
        :return: serial number of SMOD
        :rtype: str
        :raise: SmodSerialNumberUnavailable if there's no SMOD serial number for provided Test PC IP address
        """
        for test_pc in self.current_config.test_pcs:
            if test_pc.default_ssh_connection_details.addr == test_pc_ip:
                return test_pc.connections[0].serial_number

        raise SmodSerialNumberUnavailable(f"Could not find the SMOD serial number for the Test PC with IP address {test_pc_ip}")

    def _get_smod_ip_from_local_test_pc(self):
        """
        Returns IP address of SMOD connected to local Test PC.
        :return: IP address of SMOD
        :rtype: str
        :raise: MissingInitParameter if the IP address of the SMOD connected to the local Test PC could not be found.
        """
        ip = self.current_config.test_pc.connections[0].lmp_connection.addr
        if not ip:
            raise MissingInitParameter("Could not find the SMOD IP address for the local Test PC")
        return ip
